fn benchmark_campaign_verified_models(&self) -> Result<Vec<BenchmarkModelIdentity>, String> {
    if self.model_backend != ModelBackendPreference::Local {
        return Err("Automated benchmark campaigns currently require the local ModelBackend so exact installed representation identity can be verified.".to_owned());
    }
    let inventory = self
        .current_installed_inventory()
        .cloned()
        .ok_or_else(|| "Discover installed local models before starting a campaign.".to_owned())?;
    let mut models = Vec::new();
    for installed in &inventory.models {
        if !self.benchmark_campaign_models.contains(&installed.name) {
            continue;
        }
        let config = NativeModelConfig::Local(LocalModelConfig {
            endpoint: self.local_model_endpoint.clone(),
            model: installed.name.clone(),
        });
        models.push(model_identity(
            config.backend_id(),
            &installed.name,
            Some(&inventory),
        ));
    }
    if models.len() != self.benchmark_campaign_models.len() {
        return Err("One or more selected campaign models are no longer present in the current installed-model inventory.".to_owned());
    }
    Ok(models)
}

fn build_benchmark_campaign_draft(&self) -> Result<BenchmarkCampaign, String> {
    let models = self.benchmark_campaign_verified_models()?;
    if models.is_empty() {
        return Err("Select at least one exact installed model for the campaign.".to_owned());
    }
    let tasks = BENCHMARK_TASKS
        .iter()
        .enumerate()
        .filter(|(_, task)| self.benchmark_campaign_tasks.contains(task.id))
        .map(|(index, task)| {
            CampaignTaskPlan::for_task(task.id, 0x0156_0000_u64 + index as u64)
        })
        .collect::<Result<Vec<_>, _>>()?;
    if tasks.is_empty() {
        return Err("Select at least one versioned benchmark task.".to_owned());
    }
    BenchmarkCampaign::new(BenchmarkCampaignPlan {
        schema_version: CAMPAIGN_SCHEMA_VERSION,
        corpus_version: BENCHMARK_CORPUS_VERSION.to_owned(),
        benchmark_harness_version: BENCHMARK_HARNESS_VERSION.to_owned(),
        campaign_harness_version: CAMPAIGN_HARNESS_VERSION.to_owned(),
        schedule_version: CAMPAIGN_SCHEDULE_VERSION.to_owned(),
        candidates: models
            .into_iter()
            .map(|model| CampaignCandidate {
                model,
                source: CampaignCandidateSource::installed(),
            })
            .collect(),
        tasks,
        repetitions: self.benchmark_campaign_repetitions,
        comparison_class: CampaignComparisonClass::ModelComparison,
        execution_profile: self.benchmark_campaign_profile,
        execution_environments: vec![CampaignExecutionEnvironment::CompatibleBackend],
        quality: self.quality_preference,
        hardware: self.benchmark_hardware.clone(),
        workload_policy_version: WORKLOAD_POLICY_VERSION.to_owned(),
        sampling_profile: "provider-default-uncontrolled".to_owned(),
        seed_policy: CampaignSeedPolicy::ProviderUnavailable,
    })
}

fn start_benchmark_campaign(&mut self) -> Result<(), String> {
    let verified = self.benchmark_campaign_verified_models()?;
    let mut campaign = self.build_benchmark_campaign_draft()?;
    let preflight = campaign.preflight(&verified)?;
    self.benchmark_campaign_preflight = Some(preflight.clone());
    if !preflight.missing.is_empty() {
        return Err("The frozen campaign contains missing representations. Review the exact Download & Run set before acquisition.".to_owned());
    }
    campaign.start(&verified)?;
    self.benchmark_campaign_store.save(&campaign)?;
    self.benchmark_campaign = Some(campaign);
    Ok(())
}

fn persist_benchmark_campaign(&self) -> Result<(), String> {
    if let Some(campaign) = self.benchmark_campaign.as_ref() {
        self.benchmark_campaign_store.save(campaign)?;
    }
    Ok(())
}

fn resume_benchmark_campaign(&mut self) -> Result<(), String> {
    let verified = self.benchmark_campaign_verified_models()?;
    let current = self
        .benchmark_campaign
        .as_ref()
        .ok_or_else(|| "No persisted campaign is selected.".to_owned())?
        .resume_identity_for_environment(self.benchmark_hardware.clone(), &verified);
    self.benchmark_campaign
        .as_mut()
        .ok_or_else(|| "No persisted campaign is selected.".to_owned())?
        .resume(current)?;
    self.persist_benchmark_campaign()
}

fn show_benchmark_campaign(&mut self, ui: &mut egui::Ui) {
    ui.separator();
    ui.heading("Automated benchmark campaign");
    ui.small(
        "Run the frozen candidate/task plan sequentially and record each sanitized ADR 0142 result automatically. Campaigns never use the active private project as an implicit fixture.",
    );

    if self.benchmark_campaign.is_some() {
        let mut pause = false;
        let mut stop = false;
        let mut resume = false;
        let mut new_campaign = false;
        {
            let campaign = self.benchmark_campaign.as_ref().expect("checked above");
            let total = campaign.runs.len();
            let finished = campaign
                .runs
                .iter()
                .filter(|run| {
                    matches!(
                        run.status,
                        CampaignRunStatus::Completed
                            | CampaignRunStatus::Failed
                            | CampaignRunStatus::Rejected
                    )
                })
                .count();
            let completed = campaign
                .runs
                .iter()
                .filter(|run| run.status == CampaignRunStatus::Completed)
                .count();
            let failed = campaign
                .runs
                .iter()
                .filter(|run| {
                    matches!(run.status, CampaignRunStatus::Failed | CampaignRunStatus::Rejected)
                })
                .count();
            ui.horizontal_wrapped(|ui| {
                ui.strong(format!("State: {}", campaign.state.label()));
                ui.separator();
                ui.label(format!("{} model(s)", campaign.plan.candidates.len()));
                ui.separator();
                ui.label(format!("{} task(s)", campaign.plan.tasks.len()));
                ui.separator();
                ui.label(format!("{} repetition(s)", campaign.plan.repetitions));
                ui.separator();
                ui.label(campaign.plan.execution_profile.label());
            });
            let progress = if total == 0 {
                0.0
            } else {
                finished as f32 / total as f32
            };
            ui.add(
                egui::ProgressBar::new(progress)
                    .show_percentage()
                    .text(format!("{finished}/{total} finished · {completed} passed · {failed} failed")),
            );
            ui.small(format!(
                "Campaign identity: {} · corpus {} · schedule {}",
                campaign.plan_fingerprint,
                campaign.plan.corpus_version,
                campaign.plan.schedule_version
            ));
            if let Some(next) = campaign
                .runs
                .iter()
                .find(|run| matches!(run.status, CampaignRunStatus::Pending | CampaignRunStatus::Preparing | CampaignRunStatus::Running))
            {
                let model = &campaign.plan.candidates[next.schedule.candidate_index].model.model_id;
                ui.label(format!(
                    "Next/current: {} · {} · repetition {} · {}",
                    model,
                    next.schedule.task_id,
                    next.schedule.repetition,
                    next.schedule.execution_environment.label()
                ));
            }
            ui.horizontal_wrapped(|ui| {
                pause = ui
                    .add_enabled(
                        campaign.state == BenchmarkCampaignState::Running,
                        egui::Button::new("Pause"),
                    )
                    .clicked();
                stop = ui
                    .add_enabled(
                        matches!(campaign.state, BenchmarkCampaignState::Running | BenchmarkCampaignState::Paused),
                        egui::Button::new("Stop"),
                    )
                    .clicked();
                resume = ui
                    .add_enabled(
                        matches!(campaign.state, BenchmarkCampaignState::Paused | BenchmarkCampaignState::Stopped),
                        egui::Button::new("Resume"),
                    )
                    .clicked();
                new_campaign = ui
                    .add_enabled(
                        matches!(
                            campaign.state,
                            BenchmarkCampaignState::Stopped
                                | BenchmarkCampaignState::Completed
                                | BenchmarkCampaignState::Incompatible
                        ),
                        egui::Button::new("New campaign"),
                    )
                    .clicked();
            });

            let report = campaign.report();
            ui.collapsing("Aggregate report", |ui| {
                ui.small(
                    "Task success is primary. Unavailable telemetry remains unavailable rather than becoming zero.",
                );
                for candidate in &report.candidates {
                    ui.group(|ui| {
                        ui.strong(&candidate.model_id);
                        ui.label(format!(
                            "Runs: {}/{} successful · {} failed · {} rejected · OOM {}",
                            candidate.successful,
                            candidate.attempted,
                            candidate.failed,
                            candidate.rejected,
                            candidate.oom_count
                        ));
                        ui.small(format!(
                            "Median successful elapsed: {} · generation: {} milli-token/s · load: {} · peak backend GPU: {}",
                            telemetry_count_label(&candidate.median_success_elapsed_ms, "ms"),
                            telemetry_u64_value(&candidate.median_generation_tokens_per_second_milli),
                            telemetry_count_label(&candidate.median_load_latency_ms, "ms"),
                            telemetry_bytes_label(&candidate.peak_backend_gpu_memory_bytes),
                        ));
                        ui.small(format!(
                            "Validation attempts {} · repair loops {} · human interventions {}",
                            candidate.validation_attempts,
                            candidate.repair_loops,
                            candidate.human_interventions
                        ));
                        for (task_id, task) in &candidate.per_task {
                            ui.small(format!(
                                "{task_id}: {}/{} successful · {} failed",
                                task.successful, task.attempted, task.failed
                            ));
                        }
                    });
                }
            });
        }
        if pause {
            let result = self
                .benchmark_campaign
                .as_mut()
                .ok_or_else(|| "Campaign disappeared.".to_owned())
                .and_then(BenchmarkCampaign::pause)
                .and_then(|()| self.persist_benchmark_campaign());
            if let Err(error) = result {
                self.status = Some(error);
            }
        }
        if stop {
            let result = self
                .benchmark_campaign
                .as_mut()
                .ok_or_else(|| "Campaign disappeared.".to_owned())
                .and_then(BenchmarkCampaign::stop)
                .and_then(|()| self.persist_benchmark_campaign());
            if let Err(error) = result {
                self.status = Some(error);
            }
        }
        if resume
            && let Err(error) = self.resume_benchmark_campaign()
        {
            self.status = Some(error);
        }
        if new_campaign {
            self.benchmark_campaign = None;
            self.benchmark_campaign_preflight = None;
        }
        return;
    }

    let inventory = self.current_installed_inventory().cloned();
    ui.strong("Candidate models");
    if self.model_backend != ModelBackendPreference::Local {
        ui.small(
            "Switch Model backend to Local for automated campaign selection. Hosted/enterprise evidence remains available through the manual benchmark path.",
        );
    } else if let Some(inventory) = inventory.as_ref() {
        for model in &inventory.models {
            let exact = model.digest.as_ref().is_some_and(|value| !value.trim().is_empty())
                && model.size_bytes.is_some_and(|value| value > 0)
                && model
                    .quantization_level
                    .as_ref()
                    .is_some_and(|value| !value.trim().is_empty())
                && inventory
                    .backend_version
                    .as_ref()
                    .is_some_and(|value| !value.trim().is_empty());
            let mut selected = self.benchmark_campaign_models.contains(&model.name);
            ui.horizontal_wrapped(|ui| {
                if ui
                    .add_enabled(exact, egui::Checkbox::new(&mut selected, &model.name))
                    .changed()
                {
                    if selected {
                        self.benchmark_campaign_models.insert(model.name.clone());
                    } else {
                        self.benchmark_campaign_models.remove(&model.name);
                    }
                    self.benchmark_campaign_preflight = None;
                }
                ui.small(format!(
                    "digest={} · quantization={} · size={} · runtime={}{}",
                    optional_text(model.digest.as_deref()),
                    optional_text(model.quantization_level.as_deref()),
                    model
                        .size_bytes
                        .map(format_model_bytes)
                        .unwrap_or_else(|| "n/a".to_owned()),
                    optional_text(inventory.backend_version.as_deref()),
                    if exact { "" } else { " · identity incomplete" },
                ));
            });
        }
    } else {
        ui.small("Discover installed local models to freeze exact candidate identities.");
    }

    ui.strong("Task plan");
    ui.horizontal_wrapped(|ui| {
        for task in BENCHMARK_TASKS {
            let mut selected = self.benchmark_campaign_tasks.contains(task.id);
            if ui.checkbox(&mut selected, task.label).changed() {
                if selected {
                    self.benchmark_campaign_tasks.insert(task.id.to_owned());
                } else {
                    self.benchmark_campaign_tasks.remove(task.id);
                }
                self.benchmark_campaign_preflight = None;
            }
        }
    });
    ui.horizontal_wrapped(|ui| {
        ui.label("Measured repetitions");
        if ui
            .add(
                egui::DragValue::new(&mut self.benchmark_campaign_repetitions)
                    .range(1..=20),
            )
            .changed()
        {
            self.benchmark_campaign_preflight = None;
        }
        if self.benchmark_campaign_repetitions == 1 {
            ui.weak("Smoke run; not a repeated comparison.");
        } else {
            ui.small("Default comparison uses three repetitions.");
        }
        ui.separator();
        ui.label("Profile");
        for profile in [CampaignExecutionProfile::Warm, CampaignExecutionProfile::Cold] {
            if ui
                .selectable_value(
                    &mut self.benchmark_campaign_profile,
                    profile,
                    profile.label(),
                )
                .changed()
            {
                self.benchmark_campaign_preflight = None;
            }
        }
    });
    ui.small(
        "Model comparison freezes one compatible backend environment. Windows-native vs WSL2 is a separate runtime-characterization campaign and is not mixed into model ranking.",
    );

    let can_start = self.model_backend == ModelBackendPreference::Local
        && !self.benchmark_campaign_models.is_empty()
        && !self.benchmark_campaign_tasks.is_empty()
        && inventory.is_some();
    if ui
        .add_enabled(can_start, egui::Button::new("Run Benchmark"))
        .clicked()
    {
        match self.start_benchmark_campaign() {
            Ok(()) => {
                self.status = Some(
                    "Started the explicit machine-local benchmark campaign; automatic evidence recording is authorized only for this frozen plan.".to_owned(),
                );
            }
            Err(error) => self.status = Some(error),
        }
    }
    if let Some(preflight) = self.benchmark_campaign_preflight.as_ref() {
        if preflight.missing.is_empty() {
            ui.small("Preflight: all selected representations are already installed and exact.");
        } else {
            ui.group(|ui| {
                ui.strong("Download & Run review");
                for missing in &preflight.missing {
                    ui.label(format!(
                        "{} · {} · transfer {} · storage {} · {}",
                        missing.representation.model_id,
                        missing.representation.quantization,
                        format_model_bytes(missing.transfer_size_bytes),
                        format_model_bytes(missing.storage_size_bytes),
                        missing.license,
                    ));
                }
                ui.small(format!(
                    "Total transfer {} · storage {}. Approval is scoped to this exact frozen set.",
                    format_model_bytes(preflight.total_transfer_size_bytes),
                    format_model_bytes(preflight.total_storage_size_bytes),
                ));
                ui.add_enabled(false, egui::Button::new("Download & Run"));
                ui.small(
                    "Managed acquisition is owned by ADR 0155; until that runtime lands, missing representations are not downloaded by the campaign layer.",
                );
            });
        }
    }
}

